  function createMcpRow(){const row=document.createElement("div");row.className="mcp-row";row.innerHTML='<button class="remove-repeater icon-button" type="button" aria-label="Remove MCP server"><span class="material-symbols-outlined">close</span></button><label>Name<input class="text-input mcp-name" autocomplete="off" placeholder="github"></label><label>URL<input class="text-input mcp-url" autocomplete="off" placeholder="https://…"></label><label class="span-two">Command<input class="text-input mcp-command" autocomplete="off" placeholder="npx -y server-package"></label><label>Arguments <span>JSON array</span><textarea class="text-control mcp-args" rows="2" placeholder="[]"></textarea></label><label>Environment <span>JSON object</span><textarea class="text-control mcp-env" rows="2" placeholder="{}"></textarea></label><label>Auth mode<input class="text-input mcp-auth" autocomplete="off" placeholder="oauth"></label><label>Bearer token<input class="text-input mcp-token" type="password" autocomplete="new-password" placeholder="Not stored in browser"></label>';row.querySelector(".remove-repeater").addEventListener("click",()=>row.remove());return row}
