  async function createProfile(){formError("create-profile-error");const name=$("create-profile-name").value.trim();if(!name){formError("create-profile-error","Enter a profile name.");return}const source=document.querySelector('input[name="create-source"]:checked')?.value||"blank",provider=$("create-provider").value.trim(),model=$("create-model").value.trim();if(Boolean(provider)!==Boolean(model)){formError("create-profile-error","Provider and model must be supplied together.");return}let mcpServers;try{mcpServers=collectMcpServers()}catch(error){formError("create-profile-error",error.message);return}const payload={name,clone_all:source!=="blank"&&$("create-clone-all").checked,clone_channels:source!=="blank"&&$("create-clone-channels").checked,no_skills:source==="blank"&&$("create-no-skills").checked,mcp_servers:mcpServers,keep_skills:$("create-keep-skills").value.split(",").map(x=>x.trim()).filter(Boolean),hub_skills:$("create-hub-skills").value.split(/\r?\n/).map(x=>x.trim()).filter(Boolean)},description=$("create-profile-description").value.trim();if(description)payload.description=description;if(provider){payload.provider=provider;payload.model=model}if(source==="current")payload.clone_from=state.selected;else if(source==="default")payload.clone_from_default=true;const button=$("create-profile-submit"),done=setBusy(button,true,"Creating…");try{const result=await api("/profiles",{method:"POST",body:JSON.stringify(payload)});$("create-profile-dialog").close();resetCreateDialog();state.selected=String(result?.name||name);toast(`Profile ${state.selected} created`);await refreshWorkspace();if(result?.model_error)toast(`Profile created, but Hermes did not assign the model: ${result.model_error}`,true)}catch(error){formError("create-profile-error",error.message)}finally{done()}}
